def norm(s):
    s=unicodedata.normalize('NFKD',s.lower()); s=''.join(c for c in s if not unicodedata.combining(c))
    return re.sub(r'[^a-z0-9]+',' ',s).strip()
m=json.load(open(D+'merged.json'))
ex=set()
for c,v in m['cats'].items():
    for x in v: ex.add(norm(x['q']))
random.seed(11)
out={}
for name,L in (("Film i TV",F),("Glazba",G)):
    res=[]
    for i,t in enumerate(L):
        q,c,*w=t
        assert len(set([c]+w))==4, t
        if norm(q) in ex: print('DUP',q); continue
        o=w[:]; random.shuffle(o); a=i%4; o.insert(a,c)
        if len(q)>110: print('LONG Q',len(q),q)
        for x in o:
            if len(x)>30: print('LONG O',x)
        res.append({"q":q,"o":o,"a":a})
    out[name]=res
    print(name,len(res),[sum(1 for r in res if r['a']==k) for k in range(4)])
json.dump({"cats":out},open(D+'r2_11.json','w',encoding='utf-8'),ensure_ascii=False,indent=1)
